INSERT INTO mathchakchak.character_collaboration_role_translation (policy_version,locale,chakchaki_role,gongsickyi_role,verification_status)
VALUES
  ('pet-collab-v1','ko','선수 개념을 진단하고 그림·상황으로 연결하며 오개념을 찾아 단계별 힌트와 회고 질문을 제공합니다.','기호를 정의하고 공식을 유도하며 값 대입·계산·단위를 검산하고 복습 시점을 관리합니다.','SOURCE_ALIGNED'),
  ('pet-collab-v1','zh-CN','诊断先备概念，用图示和情境建立联系，发现误解并提供分步提示与反思问题。','定义符号、推导公式，检查代入、计算和单位，并安排复习时点。','TRANSLATION_REVIEW_REQUIRED'),
  ('pet-collab-v1','ja','前提概念を診断し、図や場面と結び付け、誤概念を見つけて段階的なヒントと振り返りの問いを提示します。','記号を定義して公式を導き、代入・計算・単位を確認し、復習時期を管理します。','TRANSLATION_REVIEW_REQUIRED'),
  ('pet-collab-v1','en','Diagnoses prerequisite ideas, connects visuals and situations, detects misconceptions, and provides scaffolded hints and reflection prompts.','Defines symbols, derives formulas, checks substitution, calculation, and units, and schedules review.','TRANSLATION_REVIEW_REQUIRED'),
  ('pet-collab-v1','es','Diagnostica los conocimientos previos, conecta imágenes y situaciones, detecta errores conceptuales y ofrece pistas graduales y preguntas de reflexión.','Define símbolos, deduce fórmulas, comprueba sustituciones, cálculos y unidades, y programa el repaso.','TRANSLATION_REVIEW_REQUIRED'),
  ('pet-collab-v1','fr','Diagnostique les prérequis, relie les représentations et les situations, repère les erreurs et propose des indices progressifs et des questions de réflexion.','Définit les symboles, déduit les formules, vérifie les substitutions, les calculs et les unités, puis planifie la révision.','TRANSLATION_REVIEW_REQUIRED'),
  ('pet-collab-v1','it','Diagnostica i prerequisiti, collega immagini e situazioni, individua gli errori concettuali e offre suggerimenti graduali e domande di riflessione.','Definisce i simboli, ricava le formule, controlla sostituzioni, calcoli e unità e pianifica il ripasso.','TRANSLATION_REVIEW_REQUIRED'),
  ('pet-collab-v1','ru','Проверяет базовые знания, связывает рисунки и ситуации, выявляет заблуждения и даёт пошаговые подсказки и вопросы для размышления.','Определяет обозначения, выводит формулы, проверяет подстановку, вычисления и единицы и планирует повторение.','TRANSLATION_REVIEW_REQUIRED')
